args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?dir ?dirLabel ?bd ?otherFilm ?otherDir ?bd2 WHERE {
  VALUES ?film { dbr:Drive_a_Crooked_Road dbr:Kingdom_in_the_Clouds }
  VALUES ?otherFilm { dbr:Drive_a_Crooked_Road dbr:Kingdom_in_the_Clouds }

  ?film dbo:director ?dir .
  ?dir dbo:birthDate ?bd .

  ?otherFilm dbo:director ?otherDir .
  ?otherDir dbo:birthDate ?bd2 .

  FILTER(?film != ?otherFilm)
  FILTER(?bd < ?bd2)

  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?dir rdfs:label ?dirLabel . FILTER(lang(?dirLabel) = "en") }
  OPTIONAL { ?otherDir rdfs:label ?otherDirLabel . FILTER(lang(?otherDirLabel) = "en") }
}

